<?php
require __DIR__.'/app/bootstrap.php';
require_once __DIR__.'/app/admin-nav.php';
$u=require_permission('customers.view');$d=db_load();$canManage=user_can($u,'customers.manage',$d);$msg='';$err='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    csrf_check();
    if(!$canManage){http_response_code(403);exit(permission_denied_page('customers.manage'));}
    $action=(string)($_POST['action']??'save');
    try{
        if($action==='sync'){
            $linked=0;db_mutate(function($x)use(&$linked,$u){$linked=customer_crm_sync_reservations($x);$x['audit'][]=['at'=>date('c'),'action'=>'customer_crm_synced','linked'=>$linked,'by'=>(int)$u['id']];return $x;});
            $msg=$linked>0?'เชื่อมประวัติการจองกับ CRM แล้ว '.$linked.' รายการ':'ข้อมูล CRM ตรงกับประวัติการจองล่าสุดแล้ว';
        }elseif($action==='save'){
            $id=max(0,(int)($_POST['id']??0));$name=trim((string)($_POST['full_name']??''));$phone=trim((string)($_POST['phone']??''));
            if($name==='')throw new RuntimeException('กรุณากรอกชื่อลูกค้า');$phoneKey=customer_crm_phone_key($phone);
            $email=trim((string)($_POST['email']??''));if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('รูปแบบอีเมลไม่ถูกต้อง');
            $birthday=trim((string)($_POST['birthday']??''));if($birthday!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$birthday))throw new RuntimeException('วันเกิดไม่ถูกต้อง');
            $tier=(string)($_POST['tier']??'standard');if(!in_array($tier,['standard','silver','gold','platinum'],true))$tier='standard';
            $tags=array_values(array_unique(array_filter(array_map('trim',explode(',',(string)($_POST['tags']??''))))));
            $payload=['full_name'=>$name,'nickname'=>trim((string)($_POST['nickname']??'')),'phone'=>$phone,'phone_key'=>$phoneKey,'email'=>$email,
                'line_user_id'=>trim((string)($_POST['line_user_id']??'')),'birthday'=>$birthday,'tier'=>$tier,'vip'=>!empty($_POST['vip'])?1:0,
                'tags'=>$tags,'notes'=>trim((string)($_POST['notes']??'')),'preferred_sales_employee_id'=>max(0,(int)($_POST['preferred_sales_employee_id']??0))?:null,
                'preferred_pr_id'=>max(0,(int)($_POST['preferred_pr_id']??0))?:null,'active'=>!empty($_POST['active'])?1:0,
                'marketing_consent'=>!empty($_POST['marketing_consent'])?1:0,'updated_at'=>date('c')];
            db_mutate(function($x)use($id,$phoneKey,$payload,$u){
                foreach($x['customers']??[] as $other)if($phoneKey!==''&&customer_crm_phone_key((string)($other['phone_key']??$other['phone']??''))===$phoneKey&&(int)($other['id']??0)!==$id)throw new RuntimeException('เบอร์โทรนี้มีอยู่ใน CRM แล้ว');
                $index=$id?customer_crm_find_index($x,$id):null;
                if($id>0&&$index===null)throw new RuntimeException('ไม่พบลูกค้าที่ต้องการแก้ไข');
                if($index===null){$row=customer_crm_defaults(array_merge($payload,['id'=>next_id($x['customers']??[]),'created_at'=>date('c')]));$x['customers'][]=$row;$customerId=(int)$row['id'];$actionName='customer_created';}
                else{$row=customer_crm_defaults(array_merge($x['customers'][$index],$payload));$x['customers'][$index]=$row;$customerId=(int)$row['id'];$actionName='customer_updated';}
                $x['audit'][]=['at'=>date('c'),'action'=>$actionName,'customer_id'=>$customerId,'by'=>(int)$u['id']];return $x;
            });
            $msg=$id?'บันทึกข้อมูลลูกค้าแล้ว':'เพิ่มลูกค้าใน CRM แล้ว';
        }else throw new RuntimeException('คำสั่งไม่ถูกต้อง');
    }catch(Throwable $e){$err=$e->getMessage();}
    $d=db_load();
}
$q=trim((string)($_GET['q']??''));$tierFilter=(string)($_GET['tier']??'');$editId=max(0,(int)($_GET['edit']??0));$edit=$editId?customer_crm_find($d,$editId):null;$metricMap=customer_crm_metric_map($d);
$customers=[];foreach($d['customers']??[] as $row){$row=customer_crm_defaults($row);$hay=mb_strtolower(implode(' ',[$row['full_name'],$row['nickname'],$row['phone'],$row['email'],implode(' ',$row['tags'])]),'UTF-8');if($q!==''&&mb_strpos($hay,mb_strtolower($q,'UTF-8'))===false)continue;if($tierFilter!==''&&$row['tier']!==$tierFilter)continue;$row['_metrics']=$metricMap[(int)$row['id']]??['reservations'=>0,'seated'=>0,'cancelled'=>0,'last_visit'=>'','last_sales'=>'','last_pr'=>''];$customers[]=$row;}
usort($customers,function($a,$b){$vip=(int)$b['vip']<=>(int)$a['vip'];if($vip!==0)return $vip;$la=(string)($a['_metrics']['last_visit']??'');$lb=(string)($b['_metrics']['last_visit']??'');return strcmp($lb,$la);});
$total=count($d['customers']??[]);$vipCount=count(array_filter($d['customers']??[],fn($c)=>!empty($c['vip'])));$returning=count(array_filter($metricMap,fn($m)=>(int)($m['reservations']??0)>1));
$sales=array_values(array_filter($d['employees']??[],fn($e)=>!empty($e['active'])&&(string)($e['position']??'')==='sales'));$prs=array_values(array_filter($d['prs']??[],fn($p)=>!empty($p['active'])));
$form=$edit??customer_crm_defaults(['active'=>1]);
?><!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customer CRM · MR BAR</title><link rel="stylesheet" href="assets/admin.css?v=1172"><link rel="stylesheet" href="assets/admin-v14.css?v=1172"><link rel="stylesheet" href="assets/customer-crm-v1314.css?v=1314"></head><body class="admin-v14-page crm-page"><div class="ambient"><i></i><i></i><i></i></div><?=admin_sidebar('customers',$u)?>
<main class="crm-shell"><header class="crm-top"><div><p>CUSTOMER / CRM & MEMBER</p><h1>Customer CRM</h1><span>ข้อมูลลูกค้าแยกตามร้าน · เชื่อมประวัติจอง · Sales / PR ผู้ดูแล · VIP & Tier</span></div><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="sync"><button class="crm-sync" <?=$canManage?'':'disabled'?>>↻ เชื่อมประวัติการจอง</button></form></header>
<?php if($msg):?><div class="crm-notice ok">✓ <?=h($msg)?></div><?php endif;?><?php if($err):?><div class="crm-notice err">⚠ <?=h($err)?></div><?php endif;?>
<section class="crm-stats"><article><small>ลูกค้าทั้งหมด</small><b><?=$total?></b><span>คนในร้านนี้</span></article><article><small>VIP</small><b><?=$vipCount?></b><span>คนที่ทำเครื่องหมาย VIP</span></article><article><small>ลูกค้ากลับมา</small><b><?=$returning?></b><span>มีการจองมากกว่า 1 ครั้ง</span></article><article><small>พร้อมเชื่อม POS</small><b><?=count(array_filter($d['customers']??[],fn($c)=>customer_crm_phone_key((string)($c['phone']??''))!==''))?></b><span>มีเบอร์โทรสำหรับ Matching</span></article></section>
<div class="crm-layout"><section class="crm-panel crm-directory"><header><div><small>MEMBER DIRECTORY</small><h2>รายชื่อลูกค้า</h2></div><a href="customers.php" class="crm-add">＋ เพิ่มลูกค้า</a></header><form method="get" class="crm-filter"><input name="q" value="<?=h($q)?>" placeholder="ค้นหาชื่อ เบอร์ อีเมล หรือ Tag"><select name="tier"><option value="">ทุก Tier</option><?php foreach(['standard'=>'Standard','silver'=>'Silver','gold'=>'Gold','platinum'=>'Platinum'] as $key=>$label):?><option value="<?=h($key)?>" <?=$tierFilter===$key?'selected':''?>><?=h($label)?></option><?php endforeach;?></select><button>ค้นหา</button></form>
<div class="crm-list"><?php if(!$customers):?><div class="crm-empty"><b>ยังไม่พบข้อมูลลูกค้า</b><span>กด “เชื่อมประวัติการจอง” เพื่อสร้าง CRM จาก Booking เดิม หรือเพิ่มลูกค้าใหม่</span></div><?php endif;?><?php foreach($customers as $customer):$m=$customer['_metrics'];?><a class="crm-customer <?=$editId===(int)$customer['id']?'active':''?>" href="customers.php?edit=<?=(int)$customer['id']?><?=($q!==''?'&q='.rawurlencode($q):'')?>"><span class="crm-avatar"><?=h(mb_strtoupper(mb_substr((string)$customer['full_name'],0,1,'UTF-8'),'UTF-8'))?></span><div><b><?=h((string)$customer['full_name'])?><?=$customer['vip']?' <em>VIP</em>':''?></b><small><?=h((string)($customer['nickname']?:$customer['phone']?:'ยังไม่มีเบอร์โทร'))?></small><span><?=h(ucfirst((string)$customer['tier']))?> · <?=$m['reservations']?> Booking<?=$m['last_visit']!==''?' · ล่าสุด '.h(substr($m['last_visit'],0,10)):''?></span></div><i>›</i></a><?php endforeach;?></div></section>
<section class="crm-panel crm-editor"><header><div><small><?=$edit?'EDIT MEMBER':'NEW MEMBER'?></small><h2><?=$edit?h((string)$edit['full_name']):'เพิ่มลูกค้าใหม่'?></h2></div><?php if($edit):?><span class="crm-id">CRM #<?=(int)$edit['id']?></span><?php endif;?></header><?php if($canManage):?><form method="post" class="crm-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)$form['id']?>"><div class="crm-form-grid"><label><span>ชื่อ-นามสกุล / ชื่อที่ใช้จอง *</span><input name="full_name" value="<?=h((string)$form['full_name'])?>" required></label><label><span>ชื่อเล่น</span><input name="nickname" value="<?=h((string)$form['nickname'])?>"></label><label><span>เบอร์โทร</span><input name="phone" inputmode="tel" value="<?=h((string)$form['phone'])?>"></label><label><span>อีเมล</span><input name="email" type="email" value="<?=h((string)$form['email'])?>"></label><label><span>LINE User ID / Link Key</span><input name="line_user_id" value="<?=h((string)$form['line_user_id'])?>" placeholder="รอเชื่อม LINE Login ได้ภายหลัง"></label><label><span>วันเกิด</span><input name="birthday" type="date" value="<?=h((string)$form['birthday'])?>"></label><label><span>Tier</span><select name="tier"><?php foreach(['standard'=>'Standard','silver'=>'Silver','gold'=>'Gold','platinum'=>'Platinum'] as $key=>$label):?><option value="<?=h($key)?>" <?=$form['tier']===$key?'selected':''?>><?=h($label)?></option><?php endforeach;?></select></label><label><span>Sales ประจำ</span><select name="preferred_sales_employee_id"><option value="0">— ยังไม่ระบุ —</option><?php foreach($sales as $employee):?><option value="<?=(int)$employee['id']?>" <?=(int)$form['preferred_sales_employee_id']===(int)$employee['id']?'selected':''?>><?=h(trim((string)$employee['code'].' · '.(string)$employee['name'],' ·'))?></option><?php endforeach;?></select></label><label><span>PR ที่ชอบ / ดูแลประจำ</span><select name="preferred_pr_id"><option value="0">— ยังไม่ระบุ —</option><?php foreach($prs as $pr):?><option value="<?=(int)$pr['id']?>" <?=(int)$form['preferred_pr_id']===(int)$pr['id']?'selected':''?>><?=h(trim((string)$pr['code'].' · '.(string)$pr['name'],' ·'))?></option><?php endforeach;?></select></label><label><span>Tags (คั่นด้วย comma)</span><input name="tags" value="<?=h(implode(', ',$form['tags']))?>" placeholder="birthday, whisky, KTV"></label><label class="wide"><span>บันทึกทีมงาน</span><textarea name="notes" rows="4" placeholder="ความชอบ ข้อควรระวัง โอกาสพิเศษ"><?=h((string)$form['notes'])?></textarea></label></div><div class="crm-switches"><label><input type="checkbox" name="vip" <?=$form['vip']?'checked':''?>><span>★ ลูกค้า VIP</span></label><label><input type="checkbox" name="marketing_consent" <?=$form['marketing_consent']?'checked':''?>><span>ยินยอมรับข่าวสาร</span></label><label><input type="checkbox" name="active" <?=$form['active']?'checked':''?>><span>เปิดใช้งาน</span></label></div><button class="crm-save">บันทึกข้อมูลลูกค้า</button></form><?php else:?><div class="crm-empty"><b>โหมดดูอย่างเดียว</b><span>บัญชีนี้ไม่มี Permission customers.manage</span></div><?php endif;?>
<?php if($edit):$metrics=$metricMap[(int)$edit['id']]??['reservations'=>0,'seated'=>0,'cancelled'=>0,'last_visit'=>'','last_sales'=>'','last_pr'=>''];?><div class="crm-history"><h3>ภาพรวมความสัมพันธ์</h3><div><span><b><?=$metrics['reservations']?></b><small>Booking</small></span><span><b><?=$metrics['seated']?></b><small>เข้าใช้บริการ</small></span><span><b><?=h($metrics['last_visit']!==''?substr($metrics['last_visit'],0,10):'—')?></b><small>ล่าสุด</small></span></div><p>Sales ล่าสุด: <b><?=h($metrics['last_sales']?:customer_crm_employee_label($d,$edit['preferred_sales_employee_id']))?></b> · PR ล่าสุด: <b><?=h($metrics['last_pr']?:customer_crm_pr_label($d,$edit['preferred_pr_id']))?></b></p></div><?php endif;?></section></div></main></body></html>
